import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = [int(data[1 + 2 * i]) for i in range(n)]
    b = [int(data[2 + 2 * i]) for i in range(n)]
    nxt = [[j for j in range(n) if j != i and a[j] <= b[i]] for i in range(n)]
    NEG = -1
    dp = [[NEG] * n for _ in range(1 << n)]
    for i in range(n):
        dp[1 << i][i] = b[i]
    best = 0
    for mask in range(1, 1 << n):
        row = dp[mask]
        for i in range(n):
            cur = row[i]
            if cur < 0:
                continue
            if cur > best:
                best = cur
            for j in nxt[i]:
                if not (mask >> j) & 1:
                    nm = mask | (1 << j)
                    v = cur + b[j]
                    if v > dp[nm][j]:
                        dp[nm][j] = v
    print(best)

